import{_ as t,o,c as a,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Projects — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Projects — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/projects"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Projects — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/projects"}]]},"headers":[],"relativePath":"user-guide/projects.md","filePath":"user-guide/projects.md","lastUpdated":1787616117000}'),r={name:"user-guide/projects.md"};function n(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="projects-—-user-guide" tabindex="-1">Projects — User Guide <a class="header-anchor" href="#projects-—-user-guide" aria-label="Permalink to &quot;Projects — User Guide&quot;">​</a></h1><h2 id="who-can-use-projects" tabindex="-1">Who can use Projects <a class="header-anchor" href="#who-can-use-projects" aria-label="Permalink to &quot;Who can use Projects&quot;">​</a></h2><p>Enable the <strong>Projects</strong> module from Marketplace (free) — no other modules are required first. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see projects where you are the <strong>assignee</strong>, a <strong>member</strong>, or the <strong>creator</strong>.</p><h2 id="board-list" tabindex="-1">Board &amp; list <a class="header-anchor" href="#board-list" aria-label="Permalink to &quot;Board &amp; list&quot;">​</a></h2><p>Open <strong>Projects</strong> from the sidebar under <strong>Workspace</strong> (after Tasks). The default view is the <strong>Board</strong> (columns by status). Switch to <strong>List</strong> for a table.</p><ul><li>Search by <strong>title</strong></li><li>Filter by status, Contact / Company / Opportunity (when those modules are installed), assignee, and <strong>My Projects</strong></li><li>KPI cards summarize totals, mine, by status, and <strong>Overdue</strong> for your scope</li><li>Table and board show assignee, members, dates, optional CRM links, and the <strong>latest note</strong></li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted project from the row menu</li><li><strong>Delete permanently</strong> requires <code>projects.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><p>Status labels:</p><table tabindex="0"><thead><tr><th>Value</th><th>Label</th></tr></thead><tbody><tr><td><code>planned</code></td><td>Planned</td></tr><tr><td><code>active</code></td><td>Active</td></tr><tr><td><code>on_hold</code></td><td>On Hold</td></tr><tr><td><code>completed</code></td><td>Completed</td></tr><tr><td><code>cancelled</code></td><td>Cancelled</td></tr></tbody></table><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New project</strong></li><li>Enter a <strong>title</strong> (required) and optional description</li><li>Optionally set <strong>starts on</strong> / <strong>ends on</strong> dates</li><li>If Contacts, Companies, or Opportunities are installed, optionally link them</li><li>Optionally set an assignee and members (requires <strong>assign</strong>)</li><li>Save — new projects start as <strong>Planned</strong>; without assign permission the creator becomes the assignee</li></ol><p>Edit from the row menu or the record page. Status changes use the status action (not free-form field edits of status).</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>Move a project with the status action:</p><ul><li><strong>Activate</strong> (<code>planned → active</code>)</li><li><strong>Put on hold</strong> (<code>active → on_hold</code>) or <strong>Resume</strong> (<code>on_hold → active</code>)</li><li><strong>Complete</strong> (<code>active → completed</code>) — terminal</li><li><strong>Cancel</strong> (<code>planned|active|on_hold → cancelled</code>) — terminal</li></ul><p>Invalid transitions (e.g. completing directly from Planned) are rejected with a validation error.</p><h2 id="members-assignment" tabindex="-1">Members &amp; assignment <a class="header-anchor" href="#members-assignment" aria-label="Permalink to &quot;Members &amp; assignment&quot;">​</a></h2><ul><li><strong>Assignee</strong> is the primary owner of the project</li><li><strong>Members</strong> are additional teammates who can see and work the project (without <strong>assign</strong>, membership grants visibility)</li><li>The assignee is <strong>not</strong> duplicated as a member</li><li>Users with <strong>assign</strong> can set/clear the assignee (<code>Assign</code>) and sync members</li><li>The assignee receives an in-app notification when someone else assigns them; newly added members are notified when they are added</li></ul><h2 id="optional-crm-links" tabindex="-1">Optional CRM links <a class="header-anchor" href="#optional-crm-links" aria-label="Permalink to &quot;Optional CRM links&quot;">​</a></h2><p>Contact, Company, and Opportunity links are <strong>soft</strong> — they only appear when the corresponding module is installed, and they are always optional. A project without links works the same as one with them.</p><h2 id="tasks-on-a-project" tabindex="-1">Tasks on a project <a class="header-anchor" href="#tasks-on-a-project" aria-label="Permalink to &quot;Tasks on a project&quot;">​</a></h2><p>When Projects is enabled, Tasks can optionally set a <strong>project</strong> (<code>project_id</code>). The link is soft: Tasks still work without Projects; linking fails validation if Projects is not entitled or you cannot see that project. See <a href="/user-guide/tasks">Tasks</a>.</p><h2 id="dates-overdue" tabindex="-1">Dates &amp; overdue <a class="header-anchor" href="#dates-overdue" aria-label="Permalink to &quot;Dates &amp; overdue&quot;">​</a></h2><p><code>starts_on</code> / <code>ends_on</code> are <strong>dates</strong> (not date-times). <strong>Overdue</strong> means the project is still open (<code>planned</code>, <code>active</code>, or <code>on_hold</code>), has an end date, and that end date is <strong>before today</strong> in the workspace <strong>Timezone</strong> (Settings → General). A project ending today is not overdue.</p><h2 id="notes-timeline" tabindex="-1">Notes &amp; timeline <a class="header-anchor" href="#notes-timeline" aria-label="Permalink to &quot;Notes &amp; timeline&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the project</li><li><strong>Timeline</strong> — history of create, update, assignment, members sync, status change, note, and delete/restore events</li></ul><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>When Projects is entitled and you have <code>projects.view</code>, the dashboard can show <strong>Active projects</strong> and <strong>Overdue projects</strong> widgets (same visibility rules as the list).</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Gantt charts, milestones, task dependencies, workload heatmaps, Calendar projection, Automation <code>create_project</code>, project tags, and <code>PRJ-</code> numbers are deferred — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',30)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
